insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afe9db16-1b83-4292-ba6f-e10ecbe6ac93', 'es', '¿Qué es el estatus social en el contexto de la atracción?', '["El éxito económico o la fama", "Solo el aspecto físico", "El número de amigos con los que llegas", "El valor que se te atribuye según cómo responden los demás a ti"]'::jsonb, 'El estatus es cómo reacciona el lugar ante ti, y transmite que se te valora socialmente.')
