insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('746b1fe5-9312-4688-8acf-78d313a7752a', 'es', 'Entras a un lugar y te presentas a varias personas. Más tarde te acercas a ella. ¿Qué te ayudó?', '["Está más abierta gracias a la prueba social que construiste", "Nada; el estatus no influye en su receptividad", "Todavía tienes que superar un estatus bajo", "El acercamiento se siente forzado"]'::jsonb, 'Las interacciones positivas suben tu estatus y la hacen más receptiva.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c790b664-f094-409a-9440-448401e0ec8e', 'es', '¿Cómo puede alguien ganar estatus social rápido en un ambiente nuevo?', '["Presentando a unas personas con otras", "Tratando con respeto al personal o a los anfitriones", "Centrándose exclusivamente en una persona", "Aportando algo positivo a la energía del grupo"]'::jsonb, 'Aportar al tejido social sube tu estatus más rápido que ir detrás de una sola persona.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d799275-6cc6-4451-9db7-bfb0e563f9bc', 'es', '¿Qué hace realmente interesante a un hombre en una conversación?', '["Vivir una vida que le da historias y perspectiva", "Tener opiniones firmes", "Ser gracioso a voluntad", "Hablar de sí mismo con seguridad"]'::jsonb, 'Una vida interesante genera experiencias reales que atraen a la gente de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8654d59-aeba-4ca6-b2c9-c6824582ae10', 'es', '¿Qué señales indican que alguien vive una vida interesante?', '["Tiene con naturalidad historias de experiencias reales", "Hace mejores preguntas por curiosidad genuina", "Habla con pasión de sus proyectos o intereses actuales", "Todas las anteriores"]'::jsonb, 'Una vida interesante genera experiencias reales que atraen a la gente de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dd4c710-136c-4930-a752-e6a21ba5f5ac', 'es', '¿Cómo cambia una vida interesante la dinámica de la conversación?', '["Convierte la charla en una actuación", "Da temas naturales sin tener que buscarlos", "Crea una energía magnética a partir de experiencias reales"]'::jsonb, 'Una vida interesante da lugar a intercambios fluidos y atractivos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a96beb76-cf2b-44bb-8339-887ee43c1e0e', 'es', '¿Por qué el misterio ayuda a la atracción?', '["La incertidumbre la mantiene mentalmente implicada y con curiosidad", "El cerebro presta más atención a lo que no puede descifrar del todo", "Le deja espacio para descubrirte en lugar de inundarla de información", "Todas las anteriores"]'::jsonb, 'El misterio mantiene la atención porque deja espacio a la curiosidad y al descubrimiento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87f62533-abcc-4fdd-ab12-24b45f5f4be0', 'es', 'Te pregunta a qué te dedicas. ¿Qué respuesta crea más misterio?', '["Explicarle con detalle tu trabajo y tus proyectos", "Decirle “Un poco de todo, sobre todo cosas creativas” y preguntarle por ella", "Contarle toda tu trayectoria profesional", "Decirle “Nada interesante” y cambiar de tema"]'::jsonb, 'Cuenta lo justo para intrigarla y deja espacio a su curiosidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f45fc9f5-e0a3-4d7b-87bc-840a0f414623', 'es', '¿Qué pasa cuando te explicas de más al principio de la conversación?', '["Su imaginación sigue activamente implicada", "No le queda nada por descubrir ni sobre lo que preguntarse", "La curiosidad se apaga a medida que la imagen se completa"]'::jsonb, 'Contarlo todo elimina la incertidumbre y reduce su implicación mental.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59011032-6b21-4d79-aaf3-ebe1fcb14211', 'es', '¿Cómo influye tu círculo social en tu seguridad con las mujeres?', '["Tu entorno hace que ciertos comportamientos sociales parezcan normales o raros", "Los amigos te enseñan directamente a atraer", "La seguridad es contagiosa a nivel biológico", "Las mujeres prefieren a los grupos antes que a las personas solas"]'::jsonb, 'Tu entorno o impulsa tu crecimiento o refuerza tus dudas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80bb97c5-90cf-434a-a890-08a1daa36c04', 'es', '¿Qué pasa cuando tus amigos evitan salir y conocer gente nueva?', '["Tus ganas de acercarte se debilitan con el tiempo", "El ambiente te empuja a no actuar", "Acercarte empieza a parecer raro e innecesario", "Todas las anteriores"]'::jsonb, 'Rodéate de gente proactiva que apoye la acción y no la evitación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3863647b-81d5-4ab3-9b63-30861c071216', 'es', '¿Qué suele hacer un círculo social orientado al crecimiento?', '["Te da un empujón cuando dudas", "Celebra el esfuerzo, no solo los resultados", "Te mantiene cómodo y conforme", "Crea oportunidades para conocer gente nueva"]'::jsonb, 'Estar con gente proactiva favorece la iniciativa en lugar de la evitación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b78be7b-c378-4416-a5d7-3266ab3c3dfc', 'es', '¿Cómo incorporas el contacto social a tu rutina?', '["Diciendo que sí a planes aunque estés cansado", "Yendo a sitios aunque quedarte en casa sea más fácil", "Uniéndote a grupos aunque no estés seguro de que te vayan a gustar", "Todas las anteriores"]'::jsonb, 'El contacto social crece con pequeñas decisiones repetidas de presentarte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49c55c64-36bd-4961-9847-6467136116c3', 'es', 'Te invitan a un evento, pero estás cansado. ¿Qué deberías priorizar?', '["Quedarte siempre en casa por comodidad", "Ir de todos modos para tener más oportunidades de contacto", "Esperar a tener la energía perfecta", "Decir que no para evitar interacciones forzadas"]'::jsonb, 'Decir que sí a pesar del cansancio aumenta tus intentos y tus posibles conexiones.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbe59913-e0d6-4e3f-a500-abe814b9551c', 'es', '¿Cómo se multiplican las conexiones sociales con el tiempo?', '["Una persona puede llevarte a muchas otras", "Las invitaciones te abren ambientes nuevos", "Cada interacción se convierte en algo"]'::jsonb, 'Una sola conexión puede abrir decenas de oportunidades indirectas. Déjate ver.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a683dd8f-530d-4c64-a862-57d8f10be86b', 'es', '¿Qué oportunidades de práctica cercanas hay en tu rutina diaria?', '["Una charla rápida con el barista de tu cafetería de siempre", "Una pequeña interacción con alguien del gimnasio a quien ves a menudo", "Un comentario en la fila de la caja del supermercado", "Todas las anteriores"]'::jsonb, 'Las pequeñas interacciones cotidianas reducen la presión y crean constancia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb06d0a0-4845-4ac7-80b4-cca9c98be6a3', 'es', 'Ves al mismo barista todas las mañanas. ¿Qué podrías hacer para practicar?', '["Esperar mejor a un lugar nocturno", "No hablar para seguir cómodo", "Hacer un pequeño comentario o conversar un momento"]'::jsonb, 'Las interacciones diarias sin presión te dan comodidad y habilidad de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219c6ef8-a1ff-4dbe-8af3-fa8686d0e3c1', 'es', '¿Cuál es la principal ventaja de practicar en tu día a día frente a los lugares nocturnos?', '["Limita las interacciones a los fines de semana", "Convierte los lugares de tu rutina en terreno de práctica", "Exige una salida especial para cada intento", "Mantiene mucho en juego para lograr mejores resultados"]'::jsonb, 'Los lugares de todos los días ofrecen oportunidades sin presión de forma ilimitada.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('614a2ff0-a42d-4640-8fe2-752885cd8ed4', 'es', '¿Qué significa “jugar de local” en los ambientes sociales?', '["La seguridad que da estar en terreno conocido", "La prueba social y el estatus que ganas al ser un habitual reconocido", "La ventaja de conocer el lugar y a la gente", "La comodidad que hace que acercarte dé menos miedo"]'::jsonb, 'Jugar de local es la prueba social y el estatus que da ser un habitual reconocido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91be9da9-35e2-4ee6-a859-ebc43437dadd', 'es', '¿Qué transmite a los demás ser un “habitual reconocido”?', '["Que claramente perteneces a ese lugar", "Que otros ya te aceptaron y respondieron por ti", "Que tienes más dinero o estatus que los visitantes normales", "Que es seguro interactuar contigo"]'::jsonb, 'Pertenencia, aval social y señales de seguridad: eso es jugar de local.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7755c8f9-1d23-4c93-b84c-9bb4a6f5047f', 'es', '¿Cómo puedes llegar a jugar de local en un gimnasio?', '["Ir con constancia a horas parecidas para que te reconozcan", "Tener breves momentos amables con el personal y los habituales", "Interactuar solo con las personas que te interesan románticamente", "Saludar a las caras conocidas que ya has visto"]'::jsonb, 'Constancia, interacciones amables con el personal y los habituales, y saludar a las caras conocidas: así se llega a jugar de local.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4a4122bd-a43e-4662-aef4-08635258b40c', 'es', '¿Qué mentalidad te ayuda más a hacer muchos intentos?', '["Cada intento le enseña algo positivo a tu sistema nervioso", "Cada acercamiento tiene que llevar a algo", "Los resultados importan más que la exposición", "Evitar la incomodidad siempre que se pueda"]'::jsonb, 'Cada interacción cuenta como entrenamiento, sea cual sea el resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('659f514c-7bf3-425d-9c1e-cf5df2bb69ef', 'es', 'Un acercamiento se siente plano y no consigues nada. ¿Cómo deberías verlo?', '["Como un intento valioso hacia la habituación", "Como un fracaso que refuerza la ansiedad", "Como prueba de que necesitas mejores frases", "Como motivo para dejarlo por hoy"]'::jsonb, 'Cada interacción, sea cual sea el resultado, suma a un aprendizaje positivo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e225e86-4aa9-4111-b01c-711e3725c89f', 'es', '¿Qué comportamientos aumentan la cantidad real de intentos?', '["Una pequeña interacción al día", "Esperar a sentirte seguro", "Intentos constantes y sin presión", "Acercarte solo cuando la atracción es muy fuerte"]'::jsonb, 'La constancia y la frecuencia importan más que la intensidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b9f59424-635d-4624-ad50-aa3dd25f6855', 'es', '¿Qué produce la repetición regular?', '["Las conexiones neuronales se fortalecen con el comportamiento repetido", "El comportamiento pasa de “algo que hago a veces” a “algo que soy”", "Evita que la ansiedad vuelva y que la evitación se arraigue", "Todas las anteriores"]'::jsonb, 'La práctica regular protege lo que ganaste y evita que tus habilidades se oxiden. Sé constante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6b9ff5d-fc7a-4e92-91d3-57411235152b', 'es', '¿Qué pasa a nivel psicológico durante los descansos largos de práctica?', '["Las habilidades se fortalecen todavía más", "La evitación y la ansiedad tienen tiempo de arraigarse", "Las conexiones neuronales siguen siendo eficientes", "El progreso se multiplica solo"]'::jsonb, 'Los descansos le dan a la mente espacio para inventar nuevas razones para no actuar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dd2cece1-3524-4319-bd95-d773079fa01b', 'es', '¿Qué comportamientos favorecen una constancia sostenible?', '["Fijar un mínimo semanal realista", "Esperar a sentirte seguro", "Evitar largos periodos entre intentos", "Contar las interacciones pequeñas como intentos válidos"]'::jsonb, 'El impulso importa más que la intensidad; el progreso viene de la continuidad, no de rachas sueltas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3529af51-9b76-41c8-868a-2a04a415dc15', 'es', '¿Qué pasa en el cambio de identidad de “practicar una habilidad” a “ser alguien que lo hace”?', '["El comportamiento se vuelve inseparable de la imagen que tienes de ti", "Dejas de necesitar que otros te confirmen que lo haces bien", "La acción pasa de “algo que hago” a “quien soy”", "Ya no hace falta valor porque no hay distancia que salvar"]'::jsonb, 'Inseparable de tu identidad, de “algo que hago” a “quien soy”, sin una distancia que exija valor: eso es el cambio de identidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('242a1957-a048-451a-9da7-8ab630640b24', 'es', '¿Por qué acercarte “ya no exige valor” una vez que se vuelve automático?', '["Lo has hecho tantas veces que el miedo desaparece por completo", "No hay distancia entre quién eres y lo que estás haciendo", "La seguridad que dan los éxitos repetidos elimina cualquier duda", "Te has vuelto tan hábil que el resultado ya no importa"]'::jsonb, 'No estás luchando contra tu forma de ser: simplemente estás expresando quién eres.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('371a7413-becb-4f2b-a50d-96a6e2786c70', 'es', '¿Qué define la mentalidad de experimentar al desarrollar una habilidad?', '["Tratar cada interacción como una actuación", "Medir el éxito por los resultados", "Tratar las interacciones como una forma de reunir información", "Evitar el rechazo"]'::jsonb, 'Cada interacción es útil porque te enseña qué ajustar la próxima vez.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a3d26a9-590a-4af0-95f0-d6c8c35f7896', 'es', 'Pruebas con el humor y no funciona dos veces. ¿Qué sugiere la mentalidad de experimentar?', '["El humor no es lo tuyo", "Dejar de acercarte", "Memorizar chistes mejores", "Probar otro tipo de humor u otro contexto"]'::jsonb, 'Cada interacción te enseña qué ajustar la próxima vez, incluso cuando no sale bien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e0261e-75cb-4bdc-917c-8d6e653f374a', 'es', '¿Cómo reduce la mentalidad de experimentar el dolor del rechazo?', '["Ata tu ego a cada resultado", "Trata las interacciones como una forma de reunir información", "Ve el rechazo como información valiosa"]'::jsonb, 'Los resultados se vuelven oportunidades para aprender, no pruebas de tu valor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d642fd6-f52e-4ce4-95a1-e14b1034c645', 'es', '¿Por qué la autenticidad mejora la conexión?', '["Garantiza la atracción", "Reduce la ansiedad", "Libera espacio mental para escuchar y leer la situación", "Evita el rechazo"]'::jsonb, 'Cuando dejas de actuar, puedes participar de verdad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8b12ca4-eea8-4651-a0ba-a39ced8e6aef', 'es', 'Eres callado y observador por naturaleza. ¿Qué estilo de coqueteo te va mejor?', '["Bromas rápidas e ida y vuelta constante", "Explicaciones largas", "Pausas y una mirada sostenida", "Hacer cumplidos todo el tiempo"]'::jsonb, 'Tu forma de crear tensión debe ir con tu temperamento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30871b25-0072-4ec6-a580-9ac5cb667148', 'es', '¿Por qué un estilo auténtico funciona mejor que las técnicas prestadas?', '["Libera recursos mentales para una conexión real", "Se apoya en las fortalezas que ya tiene tu personalidad", "Exige fingir para mantener la actuación"]'::jsonb, 'La autenticidad reduce el esfuerzo y aprovecha lo que ya te funciona.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3d6c847d-5687-4a4a-a269-96782bfa828d', 'es', 'Tus acercamientos suelen terminar rápido con respuestas corteses. ¿Cuál es tu punto de estancamiento?', '["Abrir bien para despertar su interés", "Avanzar en lo físico", "Mantener conversaciones largas", "Concretar bien"]'::jsonb, 'Los resultados cambian cuando la práctica se centra en el eslabón más débil de la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53171673-bc87-47f9-a580-371caf722388', 'es', 'Abres bien y conversas con facilidad, pero todo se queda en lo amistoso. ¿Cuál es tu punto de estancamiento?', '["La apertura", "La fluidez de la conversación", "Introducir tensión coqueta o un toque juguetón", "Concretar"]'::jsonb, 'Los resultados cambian cuando la práctica se centra en el eslabón más débil de la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4195d2ca-e36c-4bd9-bb7e-e178e5d589ca', 'es', 'Empiezas bien las conversaciones, pero enseguida se vuelven incómodas. ¿Cuál es tu punto de estancamiento?', '["Mantener la fluidez de la conversación y su interés", "Decir las frases de apertura", "Concretar y conseguir números", "Avanzar en lo físico"]'::jsonb, 'Los resultados cambian cuando la práctica se centra en el eslabón más débil de la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b31c3930-629e-4aab-974a-035d198918d4', 'es', '¿Cómo identificas con precisión tus puntos débiles?', '["Suponiendo que es un tema de seguridad en general", "Observando en qué punto fallan una y otra vez tus interacciones", "Revisando los patrones de dónde se caen las cosas siempre"]'::jsonb, 'Los puntos de estancamiento aparecen en momentos concretos en los que todo se cae una y otra vez.')
